package ui

import (
	"html/template"
	"io"
)

type AdminControlData struct {
	Email string
	Nonce string
	CSRF  string
}

var adminControlTemplate = template.Must(template.New("admin-control").Parse(`<section class="dashboard-welcome"><div><p class="eyebrow">YÖNETİM ARAÇLARI</p><h2>Platformun tamamını tek yerden yönetin.</h2><p class="dashboard-subtitle">Site, medya, güvenlik ve operasyon yetenekleri aynı Studio çalışma alanında.</p></div></section>
<section class="dashboard-grid"><article class="studio-card dashboard-card"><p class="eyebrow">SITE</p><h2>Site yönetimi</h2><p class="muted">Ayarlar, redirect ve navigation endpoint’leri.</p><div class="collection-grid"><a class="collection-tile" href="/site/settings" target="_blank"><strong>Public ayarlar ↗</strong></a><a class="collection-tile" href="/site/navigation/tr" target="_blank"><strong>TR navigation ↗</strong></a><a class="collection-tile" href="/admin/site/inbox/contact" target="_blank"><strong>Form inbox ↗</strong></a></div></article><article class="studio-card dashboard-card"><p class="eyebrow">ASSETLER</p><h2>Medya kütüphanesi</h2><p class="muted">Güvenli JPEG, PNG ve WebP yükleme akışı.</p><form class="studio-form" id="media-form" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="{{.CSRF}}"><label>Dosya<input name="file" type="file" accept="image/jpeg,image/png,image/webp" required></label><button type="submit">Medya yükle</button></form><p id="media-status" class="muted"></p></article></section>
<section class="studio-card dashboard-card"><div class="dashboard-card-head"><div><p class="eyebrow">YAPILANDIRMA</p><h2>Setting ve redirect kaydet</h2></div><span id="site-status" class="muted">Hazır</span></div><div class="dashboard-grid"><form class="studio-form" id="setting-form"><label>Ayar anahtarı<input name="key" placeholder="site.title" required></label><label>Değer<textarea name="value" rows="3" required></textarea></label><button type="submit">Ayarı kaydet</button></form><form class="studio-form" id="redirect-form"><label>Kaynak yol<input name="source_path" placeholder="/eski-sayfa" required></label><label>Hedef yol<input name="target_path" placeholder="/yeni-sayfa" required></label><label>Durum<select name="status"><option value="301">301 Kalıcı</option><option value="308">308 Kalıcı</option></select></label><button type="submit">Redirect kaydet</button></form></div></section>
<section class="studio-card dashboard-card"><div class="dashboard-card-head"><div><p class="eyebrow">ERİŞİM VE OPERASYON</p><h2>Kullanıcı, güvenlik ve sağlık</h2></div></div><div class="tool-grid"><form class="studio-form" id="invite-form"><input type="hidden" name="_csrf" value="{{.CSRF}}"><label>Davet e-postası<input name="email" type="email" required></label><label>Rol<select name="role"><option value="editor">Editor</option><option value="viewer">Viewer</option></select></label><button type="submit">Davet gönder</button></form><a class="tool-tile" href="/auth/me" target="_blank"><strong>Güvenlik ve MFA ↗</strong><small>Oturum ve MFA API</small></a><a class="tool-tile" href="/healthz" target="_blank"><strong>Healthz / Readyz ↗</strong><small>Servis sağlık kontrolleri</small></a><a class="tool-tile" href="/metrics" target="_blank"><strong>Metrikler ↗</strong><small>Operasyon metrikleri</small></a></div><p id="invite-status" class="muted"></p></section>
<section class="studio-card control-next"><div><p class="eyebrow">İÇERİK</p><h2>Haber, sayfa ve Commerce</h2><p class="muted">Mevcut modül panelleri aynı servis ve yetki katmanını kullanır.</p></div><div class="studio-actions"><a class="button" href="/admin/news#new-news">Yeni haber</a><a class="button button-quiet" href="/admin/pages">Sayfalar</a><a class="button button-quiet" href="/admin/commerce/products">Commerce</a></div></section><script nonce="{{.Nonce}}">(()=>{const csrf={{printf "%q" .CSRF}};const json=(form,url,body,status)=>{fetch(url,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(body)}).then(async r=>{if(!r.ok)throw Error(await r.text());status.textContent='Kaydedildi';form.reset()}).catch(e=>status.textContent='Hata: '+e.message)};document.getElementById('setting-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);json(e.currentTarget,'/admin/site/settings',{key:f.get('key'),value:f.get('value'),public:true},document.getElementById('site-status'))});document.getElementById('redirect-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);json(e.currentTarget,'/admin/site/redirects',{source_path:f.get('source_path'),target_path:f.get('target_path'),status:Number(f.get('status'))},document.getElementById('site-status'))});document.getElementById('media-form').addEventListener('submit',async e=>{e.preventDefault();const r=await fetch('/api/media',{method:'POST',headers:{'X-CSRF-Token':csrf},body:new FormData(e.currentTarget)});document.getElementById('media-status').textContent=r.ok?'Yüklendi; ready aşaması bekleniyor':'Yükleme başarısız'});document.getElementById('invite-form').addEventListener('submit',async e=>{e.preventDefault();const r=await fetch('/admin/auth/invites',{method:'POST',headers:{'X-CSRF-Token':csrf},body:new URLSearchParams(new FormData(e.currentTarget))});document.getElementById('invite-status').textContent=r.ok?'Davet gönderildi':'Davet gönderilemedi'})})()</script>`))

func RenderAdminControl(w io.Writer, data AdminControlData) error {
	if err := AdminStart(w, "Yönetim araçları", "Platform yönetimi", data.Nonce, "control"); err != nil {
		return err
	}
	if err := adminControlTemplate.Execute(w, data); err != nil {
		return err
	}
	return AdminEnd(w)
}
